import React, { useEffect, useRef } from 'react';
import { ExternalLink, Github, X } from 'lucide-react';

export const ProjectDetails = ({ project, language, onClose }) => {
  const closeRef = useRef(null);

  useEffect(() => {
    if (!project) return undefined;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    closeRef.current?.focus();

    const handleKeyDown = (event) => {
      if (event.key === 'Escape') onClose();
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [project, onClose]);

  if (!project) return null;

  const labels = {
    fr: { close: 'Fermer', problem: 'Problème', solution: 'Solution proposée', features: 'Fonctionnalités', tech: 'Technologies', status: 'Statut', demo: 'Voir la démo', code: 'Voir le code' },
    en: { close: 'Close', problem: 'Problem', solution: 'Proposed solution', features: 'Main features', tech: 'Technologies', status: 'Status', demo: 'View demo', code: 'View source' },
    ar: { close: 'إغلاق', problem: 'المشكلة', solution: 'الحل المقترح', features: 'الخصائص الرئيسية', tech: 'التقنيات', status: 'الحالة', demo: 'عرض التجربة', code: 'عرض الكود' },
    es: { close: 'Cerrar', problem: 'Problema', solution: 'Solución propuesta', features: 'Funciones principales', tech: 'Tecnologías', status: 'Estado', demo: 'Ver demo', code: 'Ver código' }
  }[language];

  return (
    <div
      className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 p-3 backdrop-blur-sm sm:p-6"
      role="presentation"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <section
        role="dialog"
        aria-modal="true"
        aria-labelledby="project-modal-title"
        className="relative max-h-[calc(100vh-1.5rem)] w-full max-w-4xl overflow-y-auto rounded-xl border border-[var(--line)] bg-[var(--surface)]"
      >
        <button
          ref={closeRef}
          type="button"
          onClick={onClose}
          aria-label={labels.close}
          className="absolute right-4 top-4 z-10 rounded-full border border-[var(--line)] bg-[var(--surface)] p-2 text-[var(--muted)] hover:text-[var(--ink)]"
        >
          <X size={20} />
        </button>

        <div className={`project-visual ${project.visual}`}>
          <span className="absolute bottom-5 left-5 rounded-full border border-[var(--line)] bg-[var(--page)] px-3 py-1 text-xs text-[var(--muted)]">
            {project.status}
          </span>
        </div>

        <div className="grid gap-8 p-6 sm:p-8 md:grid-cols-[1.15fr_.85fr]">
          <div>
            <p className="eyebrow">{project.category}</p>
            <h2 id="project-modal-title" className="mt-2 text-3xl font-semibold">{project.title}</h2>
            <p className="mt-4 leading-7 text-[var(--muted)]">{project.description[language]}</p>

            <div className="mt-7 grid gap-5 sm:grid-cols-2">
              <div>
                <h3 className="text-sm font-semibold">{labels.problem}</h3>
                <p className="mt-2 text-sm leading-6 text-[var(--muted)]">{project.problem}</p>
              </div>
              <div>
                <h3 className="text-sm font-semibold">{labels.solution}</h3>
                <p className="mt-2 text-sm leading-6 text-[var(--muted)]">{project.solution}</p>
              </div>
            </div>
          </div>

          <aside>
            <h3 className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">{labels.features}</h3>
            <ul className="mt-3 space-y-2">
              {project.features.map((feature) => (
                <li key={feature} className="border-b border-[var(--line)] pb-2 text-sm">{feature}</li>
              ))}
            </ul>

            <h3 className="mt-6 text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">{labels.tech}</h3>
            <div className="mt-3 flex flex-wrap gap-2">
              {project.tech.map((technology) => (
                <span key={technology} className="rounded-full border border-[var(--line)] px-2.5 py-1 text-xs">{technology}</span>
              ))}
            </div>

            <div className="mt-6 flex flex-wrap gap-3">
              {project.demo && (
                <a href={project.demo} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 rounded-md bg-[var(--accent)] px-4 py-2.5 text-sm font-semibold text-white">
                  {labels.demo}<ExternalLink size={15} />
                </a>
              )}
              {project.github && (
                <a href={project.github} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 rounded-md border border-[var(--line)] px-4 py-2.5 text-sm font-semibold">
                  <Github size={16} />{labels.code}
                </a>
              )}
            </div>
          </aside>
        </div>
      </section>
    </div>
  );
};
